export const SIMA_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/sima-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSimaStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SIMA_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
